<?php

namespace App\Domain\Operations\Backup;

use Illuminate\Process\Exceptions\ProcessTimedOutException;
use Illuminate\Support\Facades\Process;

/**
 * The external programs of a run (THR-10, AC-013-05): each started through the
 * framework's process API with an argument list, never a shell string. An argument
 * comes from configuration or is generated by the run: a temporary path under the
 * run's own folder, or the snapshot's name, which the database gave and whose form
 * is checked here. A stored file reaches age on its standard input, so that neither
 * its storage key nor any stored text ever reaches a process.
 *
 * The password reaches pg_dump in its environment, never in its arguments.
 */
final class BackupTools
{
    /** The tables whose data no backup holds (BACKUP_RECOVERY section 2). */
    public const array EXCLUDED_TABLES = ['sessions', 'password_reset_tokens', 'cache', 'cache_locks'];

    private const string SNAPSHOT = '/\A[0-9A-Fa-f]+-[0-9A-Fa-f]+(-[0-9]+)?\z/';

    public function __construct(
        private readonly BackupSettings $settings,
        private readonly Deadline $deadline,
    ) {}

    /**
     * The dump of ADR-010 item 1, from the exported snapshot. Row security stays
     * on, because the backup role is subject to the policies of
     * security_log_entries, whose read policy admits every entry (OPEN_ITEMS T-23).
     *
     * @throws BackupFailed
     */
    public function dump(string $snapshot, string $file): void
    {
        if (preg_match(self::SNAPSHOT, $snapshot) !== 1) {
            throw new BackupFailed(BackupFailure::DUMP_INVALID, 'The snapshot has another form.');
        }

        $command = [
            $this->settings->pgDump,
            '--host='.self::connection('host'),
            '--port='.self::connection('port'),
            '--username='.self::connection('username'),
            '--dbname='.self::connection('database'),
            '--no-password',
            '--format=custom',
            '--no-owner',
            '--no-privileges',
            '--enable-row-security',
            '--snapshot='.$snapshot,
        ];

        foreach (self::EXCLUDED_TABLES as $table) {
            $command[] = '--exclude-table-data=public.'.$table;
        }

        $command[] = '--file='.$file;

        $this->run($command, BackupFailure::DUMP_INVALID, ['PGPASSWORD' => self::connection('password'), 'PGSSLMODE' => self::connection('sslmode')]);
    }

    /**
     * @throws BackupFailed
     */
    public function checkArchive(string $file): void
    {
        $this->run([$this->settings->pgRestore, '--list', $file], BackupFailure::DUMP_INVALID);
    }

    /**
     * @throws BackupFailed
     */
    public function encryptFile(string $source, string $target): void
    {
        $this->run([$this->settings->age, '--encrypt', '--recipient', $this->settings->recipient, '--output', $target, $source], BackupFailure::DUMP_INVALID);
    }

    /**
     * @throws BackupFailed
     */
    public function encryptBytes(string $bytes, string $target): void
    {
        $this->run([$this->settings->age, '--encrypt', '--recipient', $this->settings->recipient, '--output', $target], BackupFailure::DUMP_INVALID, [], $bytes);
    }

    /**
     * @param  list<string>  $command
     * @param  array<string, string>  $environment
     *
     * @throws BackupFailed
     */
    private function run(array $command, BackupFailure $failure, array $environment = [], ?string $input = null): void
    {
        $this->deadline->check();

        $pending = Process::timeout($this->deadline->remaining())->env($environment);

        if ($input !== null) {
            $pending = $pending->input($input);
        }

        try {
            $result = $pending->run($command);
        } catch (ProcessTimedOutException) {
            throw new BackupFailed(BackupFailure::TIMEOUT, 'A program passed the time limit.');
        }

        if (! $result->successful()) {
            throw new BackupFailed($failure, basename($command[0]).' exit '.($result->exitCode() ?? 'none').': '.$result->errorOutput());
        }
    }

    private static function connection(string $name): string
    {
        $value = config('database.connections.pgsql_backup.'.$name);

        return is_string($value) ? $value : '';
    }
}
